from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.contrib.sites.shortcuts import get_current_site
from .models import CorporatePolicyDocument
from .serializers import PolicyDocumentSerializer

class CorporatePolicyDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, document_slug):
        current_site = get_current_site(request)
        try:
            doc = CorporatePolicyDocument.objects.get(slug=document_slug, is_published=True, sites=current_site)
        except CorporatePolicyDocument.DoesNotExist:
            return Response({'error': 'Document not found or access denied for this site'}, status=status.HTTP_404_NOT_FOUND)

        return Response(PolicyDocumentSerializer(doc).data)
